import{_ as o,l,o as e,c as s,v as t,p as h,x as r,d as E,i as m,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"剂量-尺寸曲线","description":"","frontmatter":{"title":"剂量-尺寸曲线","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/dose-to-size.md","filePath":"litho/dose-to-size.md","lastUpdated":1789023840000}'),n={name:"litho/dose-to-size.md"};function p(D,a,C,_,c,B){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="剂量-尺寸曲线" tabindex="-1">剂量-尺寸曲线 <a class="header-anchor" href="#剂量-尺寸曲线" aria-label="Permalink to &quot;剂量-尺寸曲线&quot;">​</a></h1><div class="epigraph"><p>$E_\\mathrm{size}$ 是目标 CD 上的一个点；剂量–尺寸曲线才问：剂量再漂一点，边横着走多远，疏密是否一起走。</p><footer>—— 据 Mack 对 CD(E) 与曝光宽容度的读图；产线亦称 dose–CD 曲线</footer></div><p><a href="/litho/e0-esize">上一课</a>钉死两个剂量锚点。缺口是把 \\(E_\\mathrm{size}\\) 展开成整条 \\(\\mathrm{CD}(E)\\)：产线拧剂量、算曝光宽容度、看 iso–dense 是否同向，都靠这张图。本课钉剂量–尺寸曲线。剂量与焦深如何耦成一张窗，留给<a href="/litho/dose-focus-coupling">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定焦距与照明，扫剂量，量某一类图形的 CD，得到 \\(\\mathrm{CD}(E)\\)。正胶密线通常剂量升则线变瘦（清掉区变宽）。斜率 \\(d\\mathrm{CD}/dE\\) 在目标处决定曝光宽容度：<a href="/litho/exposure-latitude">曝光宽容度</a> 把相对剂量宽度写成规格百分比；本课提供那条斜率的实验来源。</p><p>缺口不是再定义 \\(E_\\mathrm{size}\\)，而是：一条曲线只对一类图形成立。孤立线、密线、孔的 \\(\\mathrm{CD}(E)\\) 斜率与截距都不同，这就是 iso–dense 偏置随剂量走的原因。只报一个 \\(E_\\mathrm{size}\\)，看不见疏密是否在同一剂量下同时进规格。</p><h3 id="它不是衬度曲线" tabindex="-1">它不是衬度曲线 <a class="header-anchor" href="#它不是衬度曲线" aria-label="Permalink to &quot;它不是衬度曲线&quot;">​</a></h3><p>衬度曲线的纵轴是剩余厚度，横轴是大垫剂量。剂量–尺寸的纵轴是图形 CD。\\(\\gamma\\) 高通常让 \\(\\mathrm{CD}(E)\\) 更陡，但陡度还乘光学 ILS。把两张图叠名，会把光学问题写成「胶 γ 漂了」。</p><p><span class="marginnote">必须声明 ADI 还是 AEI。刻蚀偏置随密度变，AEI 的 \\(\\mathrm{CD}(E)\\) 不是胶曲线的平移副本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>曝光矩阵：剂量轴要跨过规格带两侧，以便拟合斜率，而不是只打在目标一点。同时测密/疏/反向，得到一族曲线。模拟：LPM 或轮廓仿真都能画，但验收以硅片为准。MEEF 大的层，掩模 CD 误差会让整族上下平移，看起来像剂量环失锁——要用掩模计量对拍。</p><p><a href="/litho/nils-ils">NILS</a> 预言相对 CD 误差反比于 NILS。本课的实验斜率是那句预言经过 \\(\\gamma\\) 与 \\(\\ell\\) 之后的实现。差一截，差在胶核与计量。</p>',12)),(e(),h(d,null,{default:r(()=>[m(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E5%89%82%E9%87%8F%20E%22%5D%20--%3E%20CDC%5B%22CD(E)%20%E4%B8%80%E6%97%8F%22%5D%0A%20%20G%5B%22%E5%9B%BE%E5%BD%A2%E7%B1%BB%E5%88%AB%22%5D%20--%3E%20CDC%0A%20%20CDC%20--%3E%20ES%5B%22E_size%20%E4%BA%A4%E7%82%B9%22%5D%0A%20%20CDC%20--%3E%20EL%5B%22%E6%9B%9D%E5%85%89%E5%AE%BD%E5%AE%B9%E5%BA%A6%22%5D%0A%20%20CDC%20--%3E%20DF%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E5%86%8D%E4%B9%98%E7%A6%BB%E7%84%A6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>边钉在化学阈值面上。剂量整体乘一个因子，空中像 \\(I\\) 相对阈值移动，边沿 \\(x\\) 方向的位移 \\(\\approx (\\Delta E/E)/\\mathrm{ILS}\\) 量级，再被显影非线性改形状。NILS 低的节距，同样 \\(\\Delta E\\) 走出更大 \\(\\Delta\\mathrm{CD}\\)，曲线更陡，窗先在剂量轴关上。酸扩散把 ILS 再砍一截，曲线更陡——看起来像胶很「敏」，其实是核把光学斜率吃了。</p><p>flare 抬台基，暗区接近阈值，过剂量时桥接会在 \\(\\mathrm{CD}(E)\\) 尚未走出 CD 规格时先出现。所以这张图还要叠缺陷判据，不能只看平均 CD。</p><p><span class="marginnote">孔的 \\(\\mathrm{CD}(E)\\) 往往比线更陡，因为二维边更吃 NILS。同一层不要用线的宽容度签核孔。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不在这里画完整 E–D 面积——下一课加焦轴。不重推瑞利 CD。随机尾部会让「平均 CD 仍在曲线上」的晶圆已经缺孔，均值曲线仍然要画，只是不能当良率的充分条件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\mathrm{CD}(E)\\) 把 \\(E_\\mathrm{size}\\) 展开成斜率与疏密族。</li><li>曝光宽容度读目标处的 \\(d\\mathrm{CD}/dE\\)，不是读大垫 \\(\\gamma\\) 本身。</li><li>一类图形一条曲线；孔与线禁止混签。</li><li>声明 ADI/AEI；flare 可能让缺陷先于 CD 越界。</li><li>出处：Mack 对 CD(E) 与 EL；主干<a href="/litho/exposure-latitude">曝光宽容度</a>。</li></ul>',8))])}const f=o(n,[["render",p]]);export{A as __pageData,f as default};
